compatible.keydesc:
{
"en":"App icon display repair",
"ch":"应用内图标显示修复"
}

compatible.notes:
{
"en":"Application icon display fix: Solve the issue of incomplete display of application icons in non-full-screen mode.",
"ch":"应用内图标显示修复：解决非全屏模式下应用内图标显示不全。"
}

compatible.keydesc:
{
"en":"Remove screenshot recording restrictions",
"ch":"解除截图录屏限制"
}

compatible.notes:
{
"en":"Remove screenshot and screen recording restrictions: Resolve the issue of certain application interfaces being unable to be captured or recorded.",
"ch":"解除截图录屏限制：解决应用部分界面无法截图和录屏。"
}

{
"en":"Application virtual resolution ratio: Addressing the limitation of certain application functionalities being restricted under the system's default resolution ratio.",
"ch":"应用虚拟分辨率：解决部分应用在系统预设的分辨率下内部某些功能被限制使用。"
}

compatible.keydesc:
{
"en":"Turn off simulated touch",
"ch":"关闭模拟触摸"
}

compatible.notes:
{
"en":"Turn off simulated touch: Solve the problem of remote control applications being unable to operate the scroll wheel.",
"ch":"关闭模拟触摸：解决远控类应用无法操作滚轮的问题。"
}

compatible.keydesc:
{
"en":"Window size limit",
"ch":"限制应用内窗口大小"
}

compatible.notes:
{
"en":"Limit the screen size used for pop-ups within the app to the current size of the app window.",
"ch":"限制应用内弹窗使用的屏幕尺寸为当前应用窗口尺寸。"
}

{
"en":"apply resource resolution:  Addressing Layout Display Issues for Certain Applications (e.g., WeChat) at System-Preset Resolutions",
"ch":"应用资源分辨率：解决部分应用（如微信）在系统预设的分辨率下布局显示过大或过小。"
}

{
"en":"Forced maximized launch: Resolves the issue of some applications not adapting to the free window during their activity lifecycle.",
"ch":"强制最大化启动：解决部分应用活动生命周期没有适配自由窗口问题。"
}

{
"en":"Force portrait mode display: Resolves the issue of repeated crashes after dragging and scaling some windows in certain applications.",
"ch":"强制竖屏显示：解决部分应用部分窗口拖拽缩放后反复闪退问题。"
}

compatible.keydesc:
{
"en":"Min bounds visible width",
"ch":"窗口显示最小宽度"
}

compatible.notes:
{
"en":"Min bounds visible width: Optimizes the zooming experience in small windows for some applications such as maps.",
"ch":"窗口显示最小宽度：优化地图类等部分应用小窗下的缩放操作体验。"
}

compatible.keydesc:
{
"en":"Min bounds visible height",
"ch":"窗口显示最小高度"
}

compatible.notes:
{
"en":"Min bounds visible height: Optimizes the zooming experience in small windows for some applications such as maps.",
"ch":"窗口显示最小高度：优化地图类等部分应用小窗下的缩放操作体验。"
}
